// Estrae dall'evento di Meta i commenti nuovi: un elemento per ogni commento.
// Solo trasformazione di dati, nessuna chiamata esterna.
// Il testo arrivato qui serve solo a scartare gli eventi vuoti: più avanti ogni commento
// viene RILETTO da Meta con il suo ID, quindi un evento falso non può far fare nulla.
const SOLO_CIFRE = /^\d{5,30}$/;
const ID_COMMENTO = /^\d{5,30}(_\d{5,30})?$/;
const risultati = [];
const visti = new Set();

for (const elemento of $input.all()) {
  const corpo = (elemento.json && elemento.json.body) || {};
  const oggetto = corpo.object;
  const voci = Array.isArray(corpo.entry) ? corpo.entry : [];
  for (const voce of voci) {
    if (!voce) continue;
    const accountId = voce.id === undefined || voce.id === null ? '' : String(voce.id);
    const modifiche = Array.isArray(voce.changes) ? voce.changes : [];
    for (const modifica of modifiche) {
      if (!modifica) continue;
      const v = modifica.value || {};
      const da = v.from || {};
      let commento = null;
      let testoEvento = '';
      if (oggetto === 'instagram' && modifica.field === 'comments') {
        commento = { piattaforma: 'instagram', account_id: accountId, comment_id: String(v.id ?? ''), parent_id: String(v.parent_id ?? '') };
        testoEvento = String(v.text ?? '');
      } else if (oggetto === 'page' && modifica.field === 'feed' && v.item === 'comment' && v.verb === 'add') {
        commento = { piattaforma: 'facebook', account_id: accountId, comment_id: String(v.comment_id ?? ''), parent_id: String(v.parent_id ?? '') };
        testoEvento = String(v.message ?? '');
      }
      if (!commento) continue;                                          // like, post, modifiche, cancellazioni…
      if (!SOLO_CIFRE.test(commento.account_id) || !ID_COMMENTO.test(commento.comment_id)) continue; // ID non validi
      if (da.id !== undefined && String(da.id) === commento.account_id) continue; // scritto dall'account stesso
      if (!testoEvento.trim()) continue;                                // senza testo (solo foto, sticker, GIF)
      const chiave = commento.piattaforma + ':' + commento.comment_id;
      if (visti.has(chiave)) continue;                                  // doppione dentro lo stesso evento
      visti.add(chiave);
      if (!ID_COMMENTO.test(commento.parent_id)) commento.parent_id = '';
      risultati.push({ json: commento });
    }
  }
}
return risultati;

// Cerca nella scheda «Clienti» il cliente a cui appartiene l'account del commento.
// ── Funzioni di servizio (le stesse in tutti i nodi Code di questo workflow) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Telegram usa il "Markdown semplice": i caratteri _ * ` [ scritti dai clienti vanno neutralizzati,
// altrimenti Telegram rifiuta il messaggio (succede con nomi come mario_rossi_88).
const md = (v) => testo(v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const link = (etichetta, url) => {
  const u = testo(url).replace(/\)/g, '%29').replace(/\s/g, '');
  return /^https?:\/\//i.test(u) ? '[' + etichetta + '](' + u + ')' : '';
};
// Unisce le righe di un messaggio: toglie quelle vuote per caso e i doppi a capo.
const unisci = (righe) => righe.filter((r) => r !== null && r !== undefined && r !== false)
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();
const NOME_PIATTAFORMA = { instagram: 'Instagram', facebook: 'Facebook' };
// Data e ora di Piacenza/Roma nel formato AAAA-MM-GG HH:MM
const dataOra = (iso) => {
  let d = iso ? new Date(String(iso).replace(/([+-]\d{2})(\d{2})$/, '$1:$2')) : new Date();
  if (isNaN(d.getTime())) d = new Date();
  const p = {};
  for (const x of new Intl.DateTimeFormat('it-IT', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit',
    day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day + ' ' + p.hour + ':' + p.minute;
};
// ── fine funzioni di servizio ──
const c = $('Ricevi un commento da lavorare').first().json;
const si = (v) => ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(testo(v).toLowerCase());
const colonna = c.piattaforma === 'instagram' ? 'ig_user_id' : 'fb_page_id';
const idAccount = testo(c.account_id);
const righe = $input.all().map((i) => i.json || {});

let riga = righe.find((r) => testo(r[colonna]) !== '' && testo(r[colonna]) === idAccount);
let avvisoFormato = '';
if (!riga) {
  // Rete di sicurezza: se nel foglio l'ID è salvato come NUMERO, Google ne arrotonda le ultime cifre.
  riga = righe.find((r) => typeof r[colonna] === 'number' && r[colonna] === Number(idAccount));
  if (riga) avvisoFormato = 'Nel foglio Clienti la colonna ' + colonna + ' è salvata come numero: mettetela in formato «Testo normale».';
}

const commento = { piattaforma: c.piattaforma, account_id: idAccount, comment_id: testo(c.comment_id), parent_id: testo(c.parent_id) };
if (!riga) {
  return [{ json: { ...commento, cliente_ok: false, motivo_stop: 'Nessun cliente nel foglio con ' + colonna + ' = ' + idAccount } }];
}
if (!si(riga.attivo)) {
  return [{ json: { ...commento, cliente_ok: false, motivo_stop: 'Il cliente «' + testo(riga.cliente) + '» non è attivo' } }];
}
return [{
  json: {
    ...commento,
    cliente_ok: true,
    avviso_formato: avvisoFormato,
    cliente: {
      cliente: testo(riga.cliente),
      nome_locale: testo(riga.nome_locale) || testo(riga.cliente),
      risposte_automatiche: si(riga.risposte_automatiche),
      tono_di_voce: testo(riga.tono_di_voce),
      orari: testo(riga.orari),
      link_prenotazione: testo(riga.link_prenotazione),
      telefono: testo(riga.telefono),
      indirizzo: testo(riga.indirizzo),
      link_menu: testo(riga.link_menu),
      regole_risposte: testo(riga.regole_risposte),
    },
  },
}];

// Controlla il commento RILETTO da Meta (la fonte vera, non il testo arrivato nel webhook)
// e decide se va valutato, se va ignorato o se c'è un problema da segnalare.
// ── Funzioni di servizio (le stesse in tutti i nodi Code di questo workflow) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// Telegram usa il "Markdown semplice": i caratteri _ * ` [ scritti dai clienti vanno neutralizzati,
// altrimenti Telegram rifiuta il messaggio (succede con nomi come mario_rossi_88).
const md = (v) => testo(v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
