  const u = testo(url).replace(/\)/g, '%29').replace(/\s/g, '');
  return /^https?:\/\//i.test(u) ? '[' + etichetta + '](' + u + ')' : '';
};
// Unisce le righe di un messaggio: toglie quelle vuote per caso e i doppi a capo.
const unisci = (righe) => righe.filter((r) => r !== null && r !== undefined && r !== false)
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();
const NOME_PIATTAFORMA = { instagram: 'Instagram', facebook: 'Facebook' };
// Data e ora di Piacenza/Roma nel formato AAAA-MM-GG HH:MM
const dataOra = (iso) => {
  let d = iso ? new Date(String(iso).replace(/([+-]\d{2})(\d{2})$/, '$1:$2')) : new Date();
  if (isNaN(d.getTime())) d = new Date();
  const p = {};
  for (const x of new Intl.DateTimeFormat('it-IT', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit',
    day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day + ' ' + p.hour + ':' + p.minute;
};
// ── fine funzioni di servizio ──
const base = $('Trova il cliente').first().json;
const ig = base.piattaforma === 'instagram';
const piatt = NOME_PIATTAFORMA[base.piattaforma] || base.piattaforma;
const nomeLocale = (base.cliente && base.cliente.nome_locale) || '';

// Per Facebook prima serve il token della Pagina: se è quello a non essere arrivato, si diagnostica quello.
let r = $input.first().json || {};
if (!ig) {
  const tok = $('Prendi il token della Pagina').first().json || {};
  if (tok.statusCode !== 200 || !tok.body || !tok.body.access_token) r = tok;
}

const fine = (stato, motivo, messaggio) => [{
  json: { stato, motivo, piattaforma: base.piattaforma, account_id: base.account_id, comment_id: base.comment_id,
    cliente_nome: nomeLocale, messaggio_telegram: messaggio || '' },
}];

if (r.statusCode !== 200 || !r.body || !r.body.id) {
  const e = (r.body && r.body.error) || {};
  const codice = Number(e.code) || 0;
  const spiegazione = testo(e.message) || (typeof r.statusCode === 'number' ? 'HTTP ' + r.statusCode : 'Meta non raggiungibile');
  // 100 = il commento non esiste più (cancellato dall'autore) o è un evento di prova di Meta: niente da fare.
  if (codice === 100 || r.statusCode === 404) return fine('ignora', 'Commento non trovato su Meta: ' + spiegazione);
  const accesso = codice === 190 || codice === 102 || codice === 10 || codice === 3 || (codice >= 200 && codice <= 299);
  const messaggio = accesso
    ? unisci([
      '🔐 *Commento non lavorato* · ' + md(nomeLocale) + ' · ' + piatt,
      'Meta ha negato l\'accesso (codice ' + codice + ': ' + md(spiegazione) + ').',
      'Di solito vuol dire che il token del System User è scaduto o che all\'app manca un permesso: controllate la credenziale «Meta - System User».',
      'ID del commento: ' + md(base.comment_id),
    ])
    : unisci([
      '⏳ *Commento non lavorato* · ' + md(nomeLocale) + ' · ' + piatt,
      'Meta in questo momento non risponde (' + md(spiegazione) + ').',
      'Guardate il commento a mano nell\'app. ID del commento: ' + md(base.comment_id),
    ]);
  return fine('avvisa', (accesso ? 'Accesso negato da Meta: ' : 'Errore di Meta: ') + spiegazione, messaggio);
}

const b = r.body;
const media = (ig && b.media) || {};
const testoCommento = testo(ig ? b.text : b.message);
const autoreId = testo(b.from && b.from.id);
const autoreNome = ig ? testo((b.from && b.from.username) || b.username) : testo(b.from && b.from.name);
const genitore = ig ? testo(b.parent_id) : testo(b.parent && b.parent.id); // c'è solo se è una risposta a un altro commento
const proprietario = testo(media.username).toLowerCase();

// Mai rispondere a noi stessi: le risposte pubblicate da questo workflow tornano qui come commenti nuovi.
const nostro = (autoreId !== '' && autoreId === base.account_id)
  || (ig && autoreNome !== '' && proprietario !== '' && autoreNome.toLowerCase() === proprietario);
if (nostro) return fine('ignora', 'Commento scritto dall\'account stesso');
if (!testoCommento) return fine('ignora', 'Commento senza testo');
// Solo tag di amici (tipico dei concorsi «tagga 2 amici»): niente AI, niente avvisi.
const senzaTag = testoCommento.replace(/@[\w.]+/g, '').replace(/[\s\p{P}\p{S}\p{Extended_Pictographic}‍️]/gu, '');
if (/@[\w.]+/.test(testoCommento) && senzaTag === '') return fine('ignora', 'Solo tag di amici');

return [{
  json: {
    stato: 'ok',
    piattaforma: base.piattaforma,
    account_id: base.account_id,
    comment_id: base.comment_id,
    parent_id: genitore,
    cliente: base.cliente,
    avviso_formato: base.avviso_formato || '',
    testo: taglia(testoCommento, 3000),
    autore_id: autoreId,
    autore_nome: autoreNome,
    link: testo(ig ? media.permalink : b.permalink_url),
    didascalia: ig ? taglia(media.caption, 600) : '',
    creato_il: testo(ig ? b.timestamp : b.created_time),
  },
}];

// Prepara la domanda per Claude: le istruzioni (con la scheda del locale) e il commento.
// Solo testo: la chiamata vera la fa il nodo «Chiedi a Claude».
// ── Funzioni di servizio (le stesse in tutti i nodi Code di questo workflow) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const taglia = (v, n) => { const s = testo(v); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
